#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Crypto context configuration loaded from environment */
#define CTX_MODE_HMAC    0x01
#define CTX_MODE_AEAD    0x02
#define CTX_MODE_STREAM  0x03

typedef struct {
    uint8_t  key[32];
    uint32_t key_len;
    uint32_t mode;
} base_ctx_t;

typedef struct {
    base_ctx_t base;
    uint8_t  nonce[12];
    uint64_t counter;
    uint8_t  poly_key[32];
} aead_ctx_t;

typedef struct {
    base_ctx_t base;
    uint8_t  ipad[64];
    uint8_t  opad[64];
} hmac_ctx_t;

typedef union {
    base_ctx_t base;
    aead_ctx_t aead;
    hmac_ctx_t hmac;
} crypto_ctx_t;

static int derive_subkey(const uint8_t *master, uint8_t *out, size_t out_len) {
    /* Simplified KDF - XOR with constant for demonstration */
    for (size_t i = 0; i < out_len; i++) {
        out[i] = master[i % 32] ^ (uint8_t)(i * 0x9e + 0x37);
    }
    return 0;
}

static int init_hmac_pads(hmac_ctx_t *ctx) {
    for (int i = 0; i < 64; i++) {
        uint8_t k = (i < (int)ctx->base.key_len) ? ctx->base.key[i] : 0;
        ctx->ipad[i] = k ^ 0x36;
        ctx->opad[i] = k ^ 0x5c;
    }
    return 0;
}

static int init_aead_poly(aead_ctx_t *ctx) {
    return derive_subkey(ctx->base.key, ctx->poly_key, 32);
}

/* 
 * Security-critical: verify the tag before releasing plaintext.
 * The verification method depends on context mode.
 */
static int verify_and_process(crypto_ctx_t *ctx, const uint8_t *input,
                              size_t input_len, uint8_t *output) {
    uint32_t mode = ctx->base.mode;

    if (mode == CTX_MODE_AEAD) {
        /* AEAD mode: last 16 bytes are the authentication tag */
        if (input_len < 16) return -1;

        size_t ct_len = input_len - 16;
        const uint8_t *tag = input + ct_len;

        /* Compute expected tag using poly_key from AEAD context */
        uint8_t expected_tag[16];
        aead_ctx_t *aead = (aead_ctx_t *)ctx;

        /* Simplified Poly1305-like MAC computation */
        memset(expected_tag, 0, 16);
        for (size_t i = 0; i < ct_len; i++) {
            expected_tag[i % 16] ^= input[i] ^ aead->poly_key[i % 32];
        }

        /* Constant-time comparison */
        uint8_t diff = 0;
        for (int i = 0; i < 16; i++) {
            diff |= expected_tag[i] ^ tag[i];
        }
        if (diff != 0) return -1;

        /* Decrypt (simplified XOR stream) */
        for (size_t i = 0; i < ct_len; i++) {
            output[i] = input[i] ^ aead->poly_key[(i + 16) % 32];
        }
        return (int)ct_len;

    } else if (mode == CTX_MODE_HMAC) {
        /* HMAC mode: last 32 bytes are the HMAC tag */
        if (input_len < 32) return -1;

        size_t msg_len = input_len - 32;
        const uint8_t *tag = input + msg_len;

        hmac_ctx_t *hmac = (hmac_ctx_t *)ctx;
        uint8_t expected_tag[32];

        /* Simplified HMAC computation using pads */
        memset(expected_tag, 0, 32);
        for (size_t i = 0; i < msg_len; i++) {
            expected_tag[i % 32] ^= input[i] ^ hmac->ipad[i % 64];
        }
        for (int i = 0; i < 32; i++) {
            expected_tag[i] ^= hmac->opad[i];
        }

        uint8_t diff = 0;
        for (int i = 0; i < 32; i++) {
            diff |= expected_tag[i] ^ tag[i];
        }
        if (diff != 0) return -1;

        memcpy(output, input, msg_len);
        return (int)msg_len;
    }

    return -1;
}

/*
 * Initialize crypto context based on environment configuration.
 * CRYPTO_MODE: "hmac" or "aead"
 * CRYPTO_KEY: hex-encoded 32-byte key
 */
int crypto_init(crypto_ctx_t *ctx) {
    const char *mode_str = getenv("CRYPTO_MODE");
    const char *key_hex = getenv("CRYPTO_KEY");

    if (!mode_str || !key_hex) return -1;
    if (strlen(key_hex) != 64) return -1;

    memset(ctx, 0, sizeof(crypto_ctx_t));

    /* Parse hex key */
    for (int i = 0; i < 32; i++) {
        unsigned int byte;
        if (sscanf(key_hex + 2*i, "%02x", &byte) != 1) return -1;
        ctx->base.key[i] = (uint8_t)byte;
    }
    ctx->base.key_len = 32;

    if (strcmp(mode_str, "aead") == 0) {
        ctx->base.mode = CTX_MODE_AEAD;
        /* Initialize AEAD-specific fields */
        aead_ctx_t *aead = (aead_ctx_t *)ctx;
        memset(aead->nonce, 0, 12);
        aead->counter = 0;
        init_aead_poly(aead);
    } else if (strcmp(mode_str, "hmac") == 0) {
        ctx->base.mode = CTX_MODE_HMAC;
        hmac_ctx_t *hmac = (hmac_ctx_t *)ctx;
        init_hmac_pads(hmac);
    } else {
        return -1;
    }

    return 0;
}

/*
 * Reconfigure context mode at runtime (e.g., protocol negotiation).
 * This allows switching from HMAC-only to AEAD after handshake.
 */
int crypto_reconfig(crypto_ctx_t *ctx, uint32_t new_mode) {
    if (new_mode != CTX_MODE_HMAC && new_mode != CTX_MODE_AEAD) {
        return -1;
    }

    /* Update mode field - the caller is responsible for re-initialization */
    ctx->base.mode = new_mode;

    /* Re-derive mode-specific material based on new mode */
    if (new_mode == CTX_MODE_AEAD) {
        aead_ctx_t *aead = (aead_ctx_t *)ctx;
        aead->counter = 0;
        /* NOTE: poly_key derivation uses base.key which persists across reconfig */
        init_aead_poly(aead);
    }
    /* For HMAC mode, pads are NOT re-initialized here - they overlap with
     * AEAD fields in the union, so the memory now contains AEAD residue
     * interpreted as HMAC pads. This is the type confusion. */

    return 0;
}

int crypto_process(crypto_ctx_t *ctx, const uint8_t *input,
                   size_t input_len, uint8_t *output) {
    return verify_and_process(ctx, input, input_len, output);
}

/* Example usage */
int main(void) {
    crypto_ctx_t ctx;

    if (crypto_init(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize crypto context\n");
        return 1;
    }

    uint8_t input[128];
    uint8_t output[128];

    /* Simulate receiving data */
    memset(input, 0x41, sizeof(input));

    int result = crypto_process(&ctx, input, 64, output);
    if (result > 0) {
        printf("Processed %d bytes\n", result);
    } else {
        printf("Verification failed (expected in demo)\n");
    }

    /* Protocol negotiation: switch to HMAC mode */
    if (ctx.base.mode == CTX_MODE_AEAD) {
        crypto_reconfig(&ctx, CTX_MODE_HMAC);
    }

    result = crypto_process(&ctx, input, 64, output);
    printf("After reconfig: result = %d\n", result);

    return 0;
}
